package io.github.sahilmakkar.chronos.task

import io.github.sahilmakkar.chronos.task.model.TaskData
import io.github.sahilmakkar.chronos.task.model.workDataOf

/**
 * Represents the outcome of a [io.github.sahilmakkar.chronos.kmpWorker.KmpWorker] task execution.
 */
sealed class TaskResult {
    /**
     * Indicates that the worker completed its work successfully.
     *
     * @property outputData Optional [TaskData] containing outputs generated by the worker.
     */
    data class Success(val outputData: TaskData = workDataOf()) : TaskResult()

    /**
     * Indicates that the worker encountered a permanent failure.
     * Dependent tasks in a chain may be skipped or stopped depending on failure policies.
     *
     * @property outputData Optional [TaskData] containing error context/payload.
     */
    data class Failure(val outputData: TaskData = workDataOf()) : TaskResult()

    /**
     * Indicates that the worker failed but wants to retry the execution later.
     * Rescheduling will respect backoff policies configured on the [io.github.sahilmakkar.chronos.task.request.TaskRequest].
     */
    object Retry : TaskResult()
}